  const w2y = Math.cos(my*0.028+t*0.45)*8+Math.sin(mx*0.022-t*0.55)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,2],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+4)*40,0.14,2.1,0],
    [400+Math.cos(t*0.55+2)*70,220+Math.sin(t*0.75+1)*50,0.11,1.8,1],
    [200+Math.sin(t*0.25+6)*110,60+Math.cos(t*0.45+5)*70,0.05,2.4,2],
    [300+Math.cos(t*0.65+4)*90,180+Math.sin(t*0.85+2)*60,0.13,1.6,0]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,tp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    if(tp===0)aS+=Math.sin(d*f-t*sp);
    else if(tp===1)iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    else mS+=Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const act=aS/4,inh=iS/3,mod=mS/3;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.5+Math.sin(sx*0.12-sy*0.09+t*2)*0.25+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2)/2.5;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
