  const reaction=Math.tanh((act-inh*0.7+mod*0.4+bg*0.3+spiral)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*1.3)*0.3+Math.sin((sx-sy)*0.2-t*0.8)*0.2)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.1*Math.abs(reaction);
  const blend=reaction*0.6+cell*0.25+micro*0.15,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,80],[15,75,110],[20,120,120],[45,160,130],[120,185,100],[200,195,70],[220,160,60],[210,110,70],[180,70,75],[120,40,80],[60,20,65],[25,12,50],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,edge=Math.abs(reaction)>0.7?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*2)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120)|0)
  ];
}
